    private final class Storage {
        var value: Fields

        init(_ value: Fields) {
            self.value = value
        }
    }

    private var storage: Storage

    private var fields: Fields {
        _read { yield storage.value }
        _modify {
            if !isKnownUniquelyReferenced(&storage) {
                storage = Storage(storage.value)
            }
            yield &storage.value
        }
    }

    public init(_ configure: (inout Fields) -> Void = { _ in }) {
        var value = Fields()
        configure(&value)
        storage = Storage(value)
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.storage === rhs.storage || lhs.fields == rhs.fields
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(fields)
    }

    public subscript<T>(dynamicMember keyPath: WritableKeyPath<Fields, T>) -> T {
        _read { yield storage.value[keyPath: keyPath] }
        _modify { yield &fields[keyPath: keyPath] }
